CREATE TABLE `dashboard_fv_card_snapshot` (
                                              `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                              `data_time` date NOT NULL COMMENT '数据时点',
                                              `card_code` varchar(64) NOT NULL COMMENT '卡片编码',
                                              `card_name` varchar(64) NOT NULL COMMENT '卡片名称',
                                              `card_data` json NOT NULL COMMENT '卡片数据',
                                              `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                              `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                              PRIMARY KEY (`id`),
                                              KEY `idx_data_time_card_code` (`data_time`,`card_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台融资视图卡片快照信息表';

CREATE TABLE `dashboard_fv_credit_info_snapshot` (
                                                     `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                                     `card_id` bigint(20) NOT NULL COMMENT '卡片id',
                                                     `credit_id` bigint(20) DEFAULT NULL COMMENT '授信ID',
                                                     `credit_code` varchar(64) DEFAULT NULL COMMENT '授信编号',
                                                     `org_name` varchar(128) DEFAULT NULL COMMENT '机构名称',
                                                     `financing_biz_type_code` varchar(32) DEFAULT NULL COMMENT '产品类型code',
                                                     `financing_biz_type_display` varchar(128) DEFAULT NULL COMMENT '产品类型display',
                                                     `credit_total_amount` decimal(20,6) DEFAULT NULL COMMENT '总授信额度',
                                                     `credit_used_amount` decimal(20,6) DEFAULT NULL COMMENT '已使用授信额度',
                                                     `is_cycle` tinyint(1) DEFAULT '0' COMMENT '是否可循环，1-是，0-否',
                                                     `deadline` date DEFAULT NULL COMMENT '授信到期日',
                                                     `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                     `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                     PRIMARY KEY (`id`),
                                                     KEY `idx_org_name` (`org_name`),
                                                     KEY `idx_deadline` (`deadline`),
                                                     KEY `idx_biz_type` (`financing_biz_type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台授信信息快照表';

CREATE TABLE `dashboard_fv_finance_info_snapshot` (
                                                      `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                                      `card_id` bigint(20) DEFAULT NULL COMMENT '卡片id',
                                                      `financing_id` bigint(20) DEFAULT NULL COMMENT '融资id',
                                                      `financing_code` varchar(64) DEFAULT NULL COMMENT '融资编号',
                                                      `org_name` varchar(128) DEFAULT NULL COMMENT '机构名称',
                                                      `financing_type_code` varchar(32) DEFAULT NULL COMMENT '融资类别Code FinancingTypeEnum',
                                                      `financing_type_display` varchar(128) DEFAULT NULL COMMENT '融资类别display FinancingTypeEnum',
                                                      `financing_month` varchar(20) DEFAULT NULL COMMENT '还款期限(月)',
                                                      `repay_way` varchar(128) DEFAULT NULL COMMENT '还款方式',
                                                      `loan_amount` decimal(20,6) DEFAULT NULL COMMENT '融资金额',
                                                      `remaining_principle_amount` decimal(20,6) DEFAULT NULL COMMENT '剩余金额',
                                                      `interest_rate` decimal(20, 6) DEFAULT NULL COMMENT '利率',
                                                      `comprehensive_interest_rate` decimal(16,6) DEFAULT NULL COMMENT '综合资金成本',
                                                      `actual_loan_date` date DEFAULT NULL COMMENT '起息日',
                                                      `actual_expire_date` date DEFAULT NULL COMMENT '到期日',
                                                      `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                      `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                      `pledge_contract_code` varchar(1024) DEFAULT NULL COMMENT '质押合同',
                                                      PRIMARY KEY (`id`),
                                                      KEY `idx_org_name` (`org_name`),
                                                      KEY `idx_financing_type` (`financing_type_code`),
                                                      KEY `idx_actual_loan_date` (`actual_loan_date`),
                                                      KEY `idx_actual_expire_date` (`actual_expire_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台融资情况快照表';

CREATE TABLE `dashboard_fv_financing_cost_snapshot` (
                                                        `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                                        `card_id` bigint(20) NOT NULL COMMENT '卡片id',
                                                        `financing_id` bigint(20) DEFAULT NULL COMMENT '融资id',
                                                        `financing_code` varchar(64) DEFAULT NULL COMMENT '融资编号',
                                                        `org_name` varchar(128) DEFAULT NULL COMMENT '机构名称',
                                                        `financing_type_code` varchar(32) DEFAULT NULL COMMENT '融资类别Code FinancingTypeEnum',
                                                        `financing_type_display` varchar(128) DEFAULT NULL COMMENT '融资类别display FinancingTypeEnum',
                                                        `financing_month` varchar(20) DEFAULT NULL COMMENT '还款期限(月)',
                                                        `repay_way` varchar(64) DEFAULT NULL COMMENT '还款方式',
                                                        `loan_amount` decimal(20,6) DEFAULT NULL COMMENT '融资金额(元)',
                                                        `remaining_principle_amount` decimal(24,6) DEFAULT NULL COMMENT '剩余金额(元)',
                                                        `comprehensive_interest_rate` decimal(16,6) DEFAULT NULL COMMENT '综合资金成本',
                                                        `actual_loan_date` date DEFAULT NULL COMMENT '起息日',
                                                        `actual_expire_date` date DEFAULT NULL COMMENT '到期日',
                                                        `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                        `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                        `related_contract_code_list` varchar(1024) DEFAULT NULL COMMENT '质押合同',
                                                        PRIMARY KEY (`id`),
                                                        KEY `idx_org_name` (`org_name`),
                                                        KEY `idx_financing_type` (`financing_type_code`),
                                                        KEY `idx_actual_loan_date` (`actual_loan_date`),
                                                        KEY `idx_actual_expire_date` (`actual_expire_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台融资成本信息快照表';

CREATE TABLE `dashboard_fv_repay_principal_interest_snapshot` (
                                                                  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                                                  `card_id` bigint(20) DEFAULT NULL COMMENT '卡片id',
                                                                  `receipt_repay_cash_flow_id` bigint(20) DEFAULT NULL COMMENT '收付现金流Id',
                                                                  `write_off_state` varchar(32) DEFAULT NULL COMMENT '核销状态编码',
                                                                  `write_off_state_display` varchar(64) DEFAULT NULL COMMENT '核销状态显示',
                                                                  `financing_id` bigint(20) DEFAULT NULL COMMENT '融资Id',
                                                                  `financing_code` varchar(64) DEFAULT NULL COMMENT '融资编号',
                                                                  `is_direct` tinyint(1) DEFAULT '0' COMMENT '是否直融(0-否,1-是)',
                                                                  `org_name` varchar(255) DEFAULT NULL COMMENT '机构名称',
                                                                  `loan_amount` decimal(24,6) DEFAULT NULL COMMENT '贷款金额',
                                                                  `loan_balance_amount` decimal(24,6) DEFAULT NULL COMMENT '贷款余额',
                                                                  `repay_total_amount` decimal(24,6) DEFAULT NULL COMMENT '应还总额',
                                                                  `repay_principal_amount` decimal(24,6) DEFAULT NULL COMMENT '应还本金',
                                                                  `repay_interest_amount` decimal(24,6) DEFAULT NULL COMMENT '应还利息',
                                                                  `repay_date` varchar(256) DEFAULT NULL COMMENT '应还日期',
                                                                  `actual_repay_amount` decimal(24,6) DEFAULT '0.00' COMMENT '实还金额',
                                                                  `repay_balance_amount` decimal(24,6) DEFAULT NULL COMMENT '还款余额',
                                                                  `repay_balance_amount_unit` varchar(16) DEFAULT '元' COMMENT '还款余额单位',
                                                                  `actual_repay_date` varchar(256) DEFAULT NULL COMMENT '实际还款日期',
                                                                  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                                  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                                  PRIMARY KEY (`id`),
                                                                  KEY `idx_financing_code` (`financing_code`),
                                                                  KEY `idx_repay_date` (`repay_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台还本付息信息表';

CREATE TABLE `dashboard_fv_repay_principal_interest_sub` (
                                                             `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Id',
                                                             `main_id` bigint(20) NOT NULL COMMENT '主表Id',
                                                             `related_proj_name` varchar(255) DEFAULT NULL COMMENT '关联项目名称',
                                                             `related_contract_code` varchar(64) DEFAULT NULL COMMENT '关联合同编号',
                                                             `rent_plan_collection_amount` decimal(24,6) DEFAULT NULL COMMENT '租金计划收款金额',
                                                             `rent_plan_collection_date` date DEFAULT NULL COMMENT '租金计划收款日期',
                                                             `bank_account_type_code` varchar(32) DEFAULT NULL COMMENT '银行账户类型编码',
                                                             `bank_account_type_display` varchar(64) DEFAULT NULL COMMENT '银行账户类型显示',
                                                             `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                             `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                             PRIMARY KEY (`id`),
                                                             KEY `idx_main_id` (`main_id`),
                                                             KEY `idx_rent_plan_collection_date` (`rent_plan_collection_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作台还本付息子列表信息表';